ten piedad de nosotros.

Santísima Trinidad, un solo Dios,

ten piedad de nosotros.

Santa María,

ruega por nosotros.

Santa Madre de Dios,

ruega por nosotros.

Santa Virgen de las vírgenes,

ruega por nosotros.

Madre de Cristo,

ruega por nosotros.

Reina concebida sin mancha de pecado original,

ruega por nosotros.

Reina del Santísimo Rosario,

ruega por nosotros.

