                meditation = LocalizedText("""En el nombre del Padre, y del Hijo, y del Espíritu Santo.

Amén.

Letanía de Nuestra Señora del Perpetuo Socorro

Señor, ten piedad de nosotros.

Cristo, ten piedad de nosotros.

Señor, ten piedad de nosotros. Cristo, óyenos.

Cristo, escúchanos.

Dios Padre celestial,

ten piedad de nosotros.

Dios Hijo, Redentor del mundo,

ten piedad de nosotros.

Dios Espíritu Santo,

ten piedad de nosotros.

Santísima Trinidad, un solo Dios,

ten piedad de nosotros.

Santa María,

ruega por nosotros.

Santa Madre de Dios,

ruega por nosotros.

Santa Virgen de las vírgenes,

ruega por nosotros.

Madre de Cristo,

ruega por nosotros.

Reina concebida sin mancha de pecado original,

ruega por nosotros.

Reina del Santísimo Rosario,

ruega por nosotros.

Nuestra Señora del Perpetuo Socorro,

ruega por nosotros.

Oh Madre del Perpetuo Socorro,

cuyo solo nombre inspira confianza,

Ven en mi ayuda, oh Madre amorosa.

Para que ame a Dios con todo mi corazón,

Ven en mi ayuda, oh Madre amorosa.

Para que en todo conforme mi voluntad

con la de tu Divino Hijo,

Ven en mi ayuda, oh Madre amorosa.

Para que huya siempre del pecado, el único mal verdadero,

Ven en mi ayuda, oh Madre amorosa.

Para que recuerde siempre mi fin último,

Ven en mi ayuda, oh Madre amorosa.

Para que reciba con frecuencia y devoción los Sacramentos,

Ven en mi ayuda, oh Madre amorosa.

Para que evite toda ocasión próxima de pecado,

Ven en mi ayuda, oh Madre amorosa.

Para que nunca descuide la oración,

Ven en mi ayuda, oh Madre amorosa.

Para que me acuerde siempre de invocarte,

sobre todo en el momento de la tentación,

Ven en mi ayuda, oh Madre amorosa.

Para que salga siempre victorioso en la hora de la tentación,

Ven en mi ayuda, oh Madre amorosa.

Para que perdone generosamente a mis enemigos,

Ven en mi ayuda, oh Madre amorosa.

Para que me levante pronto,

si tuviera la desgracia de caer en pecado mortal,

Ven en mi ayuda, oh Madre amorosa.

Para que resista con valentía las seducciones de las malas compañías,

Ven en mi ayuda, oh Madre amorosa.

Para que sea fuerte frente a mi propia inconstancia,

Ven en mi ayuda, oh Madre amorosa.

Para que no aplace de un día para otro mi conversión,

Ven en mi ayuda, oh Madre amorosa.

Para que trabaje con celo por desarraigar mis malos hábitos,

Ven en mi ayuda, oh Madre amorosa.

Para que me guste siempre servirte,

Ven en mi ayuda, oh Madre amorosa.

Para que lleve a otros a amarte y servirte,

Ven en mi ayuda, oh Madre amorosa.

Para que viva y muera en la amistad de Dios,

Ven en mi ayuda, oh Madre amorosa.

En todas las necesidades del cuerpo y del alma,

Ven en mi ayuda, oh Madre amorosa.

En la enfermedad y el dolor,

Ven en mi ayuda, oh Madre amorosa.

En la pobreza y la angustia,

Ven en mi ayuda, oh Madre amorosa.

En la persecución y el abandono,

Ven en mi ayuda, oh Madre amorosa.

En la pena y el desamparo del alma,

Ven en mi ayuda, oh Madre amorosa.

En tiempo de guerra, hambre y epidemia,

Ven en mi ayuda, oh Madre amorosa.

En todo peligro de pecado,

Ven en mi ayuda, oh Madre amorosa.

Cuando me asalten los espíritus malignos,

Ven en mi ayuda, oh Madre amorosa.

Cuando me tienten los halagos de un mundo engañoso,

Ven en mi ayuda, oh Madre amorosa.

Cuando luche contra las inclinaciones de mi naturaleza corrompida,

Ven en mi ayuda, oh Madre amorosa.

Cuando sea tentado contra la santa virtud de la pureza,

Ven en mi ayuda, oh Madre amorosa.

Cuando se acerque la muerte,

Ven en mi ayuda, oh Madre amorosa.

Cuando la pérdida de mis sentidos

me advierta que mi carrera terrena ha terminado,

Ven en mi ayuda, oh Madre amorosa.

Cuando el pensamiento de mi próximo fin

me llene de miedo y de terror,

Ven en mi ayuda, oh Madre amorosa.

Cuando, en la hora decisiva de la muerte,

el espíritu maligno intente hundir mi alma en la desesperación,

Ven en mi ayuda, oh Madre amorosa.

Cuando el sacerdote de Dios me dé

su última absolución y su última bendición,

Ven en mi ayuda, oh Madre amorosa.

Cuando mis amigos y parientes,

rodeando mi lecho, movidos a compasión,

invoquen tu clemencia en mi favor,

Ven en mi ayuda, oh Madre amorosa.

Cuando el mundo desaparezca de mi vista

y mi corazón deje de latir,

Ven en mi ayuda, oh Madre amorosa.

Cuando entregue mi alma en manos de su Creador,

Ven en mi ayuda, oh Madre amorosa.

Cuando mi alma comparezca ante su Juez Soberano,

Ven en mi ayuda, oh Madre amorosa.

Cuando se pronuncie la sentencia irrevocable,

Ven en mi ayuda, oh Madre amorosa.

Cuando esté sufriendo en el Purgatorio

y suspirando por la visión de Dios,

Ven en mi ayuda, oh Madre amorosa.

Cordero de Dios, que quitas el pecado del mundo,

perdónanos, Señor.

Cordero de Dios, que quitas el pecado del mundo,

escúchanos, Señor.

Cordero de Dios, que quitas el pecado del mundo,

ten misericordia de nosotros.

Oremos.

Oh Dios omnipotente y misericordioso, que, para socorrer al género humano, quisiste que la Santísima Virgen María fuera la Madre de Tu Hijo unigénito, concédenos, te lo suplicamos, que por su intercesión evitemos el contagio del pecado y te sirvamos con corazón puro. Por el mismo Cristo nuestro Señor.

Amén.

Oh Madre del Perpetuo Socorro, concédeme invocar siempre tu poderoso nombre, protección de los vivos y salvación de los moribundos.

Purísima María, que tu nombre esté de ahora en adelante siempre en mis labios. No tardes, Señora bendita, en socorrerme cada vez que te invoque.

En mis tentaciones, en mis necesidades, nunca dejaré de invocarte, repitiendo siempre tu sagrado nombre: María, María.

¡Qué consuelo, qué dulzura, qué confianza llena mi alma cuando pronuncio tu sagrado nombre, o incluso solo cuando pienso en ti! Doy gracias al Señor por haberte dado un nombre tan dulce, tan poderoso y tan hermoso.

Pero no me contentaré con solo pronunciar tu nombre. Que mi amor por ti me mueva siempre a saludarte como Madre del Perpetuo Socorro. Madre del Perpetuo Socorro, ruega por mí y concédeme el favor que te pido con confianza

(menciona tu petición aquí…)

(Dios te salve, María, tres veces)

En el nombre del Padre, y del Hijo, y del Espíritu Santo.

Amén.

