20 de jul""", """In the Name of the Father, and of the Son, and of the Holy Spirit.

Amen.

Litany of Our Lady of Perpetual Help

Lord, have mercy on us.

Christ, have mercy on us.

Lord, have mercy on us. Christ, hear us.

Christ, graciously hear us.

God the Father of Heaven,

Have mercy on us.

God the Son, Redeemer of the world,

Have mercy on us.

God the Holy Ghost,

Have mercy on us.

Holy Trinity, One God,

Have mercy on us.

Holy Mary,

pray for us.

Holy Mother of God,

pray for us.

Holy Virgin of virgins,

pray for us.

Mother of Christ,

pray for us.

Queen conceived without the stain of Original Sin,

pray for us.

Queen of the most Holy Rosary,

pray for us.

Our Lady of Perpetual Help,

pray for us.

O Mother of Perpetual Help,

whose very name inspires confidence,

Come to my aid, O loving Mother.

That I may love God with all my heart,

Come to my aid, O loving Mother.

That I may in all things conform my will

to that of thy Divine Son,

Come to my aid, O loving Mother.

That I may always shun sin, the only real evil,

Come to my aid, O loving Mother.

That I may always remember my last end,

Come to my aid, O loving Mother.

That I may often and devoutly receive the Sacraments,

Come to my aid, O loving Mother.

That I may avoid every proximate occasion of sin,

Come to my aid, O loving Mother.

That I may never neglect prayer,

Come to my aid, O loving Mother.

That I may ever remember to invoke thee,

particularly in time of temptation,

Come to my aid, O loving Mother.

That I may always be victorious in the hour of temptation,

Come to my aid, O loving Mother.

That I may generously pardon my enemies,

Come to my aid, O loving Mother.

That I may arise quickly,

should I have the misfortune of falling into mortal sin,

Come to my aid, O loving Mother.

That I may courageously resist the seductions of evil companions,

Come to my aid, O loving Mother.

That I may be strong against my own inconstancy,

Come to my aid, O loving Mother.

That I may not delay my conversion from day to day,

Come to my aid, O loving Mother.

That I may labor zealously to eradicate my evil habits,

Come to my aid, O loving Mother.

That I may ever love to serve thee,

Come to my aid, O loving Mother.

That I may lead others to love and serve thee,

Come to my aid, O loving Mother.

That I may live and die in the friendship of God,

Come to my aid, O loving Mother.

In all necessities of body and soul,

Come to my aid, O loving Mother.

In sickness and pain,

Come to my aid, O loving Mother.

In poverty and distress,

Come to my aid, O loving Mother.

In persecution and abandonment,

Come to my aid, O loving Mother.

In grief and dereliction of mind,

Come to my aid, O loving Mother.

In time of war, famine and contagion,

Come to my aid, O loving Mother.

In every danger of sin,

Come to my aid, O loving Mother.

When assailed by the evil spirits,

Come to my aid, O loving Mother.

When tempted by the allurements of a deceitful world,

Come to my aid, O loving Mother.

When struggling against the inclinations of my corrupt nature,

Come to my aid, O loving Mother.

When tempted against the holy virtue of purity,

Come to my aid, O loving Mother.

When death is nigh,

Come to my aid, O loving Mother.

When the loss of my senses

shall warn me that my earthly career is at an end,

Come to my aid, O loving Mother.

When the thought of my approaching dissolution

shall fill me with fear and terror,

Come to my aid, O loving Mother.

When at the decisive hour of death,

the evil spirit will endeavor to plunge my soul into despair,

Come to my aid, O loving Mother.

When the priest of God shall give me

his last absolution and his last blessing,

Come to my aid, O loving Mother.

When my friends and relations,

surrounding my bed, moved with compassion,

shall invoke thy clemency on my behalf,

Come to my aid, O loving Mother.

When the world will vanish from my sight,

and my heart will cease to beat,

Come to my aid, O loving Mother.

When I shall yield my soul into the hands of its Creator,

Come to my aid, O loving Mother.

When my soul will appear before its Sovereign Judge,

Come to my aid, O loving Mother.

When the irrevocable sentence will be pronounced,

Come to my aid, O loving Mother.

When I will be suffering in Purgatory,

and sighing for the vision of God,

Come to my aid, O loving Mother.

Lamb of God, Who takest away the sins of the world,

Spare us, O Lord.

Lamb of God, Who takest away the sins of the world,

Graciously hear us, O Lord.

Lamb of God, Who takest away the sins of the world,

Have mercy on us.

Let Us Pray.

O Almighty and merciful God, Who, in order to succor the human race, hast willed the Blessed Virgin Mary to become the Mother of Thy only-begotten Son, grant, we beseech Thee, that by her intercession we may avoid the contagion of sin and serve Thee with a pure heart, through the same Christ Our Lord.

Amen.

O Mother of Perpetual Help, grant that I may ever invoke your powerful name, the protection of the living and the salvation of the dying.

Purest Mary, let your name henceforth be ever on my lips. Delay not, Blessed Lady, to rescue me whenever I call on you.

In my temptations, in my needs, I will never cease to call on you, ever repeating your sacred name, Mary, Mary.

What a consolation, what sweetness, what confidence fills my soul when I utter your sacred name or even only think of you! I thank the Lord for having given you so sweet, so powerful, so lovely a name.

But I will not be content with merely uttering your name. Let my love for you prompt me ever to hail you Mother of Perpetual Help. Mother of Perpetual Help, pray for me and grant me the favor I confidently ask of you

(mention request here…)

(Hail Mary three times)

In the Name of the Father, and of the Son, and of the Holy Spirit.

Amen.

