Configure lembretes para não perder nenhum dia

Em nome do Pai, do Filho e do Espírito Santo.

Amém.

Ó Mãe do Perpétuo Socorro, eu vos ofereço esta novena, por intenção dos doentes, dos aflitos e atribulados, dos pobres pecadores, pelas necessidades da Igreja, por suas vocações sacerdotais, religiosas e leigas, por minha família, pelos membros da Família Excelsior e por minhas intenções particulares. Dignai-vos atender-me bondosamente. Amém!

(mencione o pedido aqui…)

Eis, aqui, ó Mãe do Perpétuo Socorro, aos vossos pés um miserável pecador, que a Vós recorre e em Vós confia., Ó Mãe de misericórdia, tende piedade de mim!, Ouço que todos Vos chamam o Refúgio e a Esperança dos pecadores;, logo então, sede Vós o meu refúgio e a minha esperança.

Por amor de Jesus Cristo, socorrei-me., Dai a mão a um mísero/a caído,, que a Vós se entrega e recomenda.

Eu bendigo e rendo graças a Deus, por se ter dignado conceder-me esta confiança em Vós, que eu considero um penhor de minha salvação

eterna. Ah! É mais do que certo que no passado, quando tive a desventura de cair,, a Vós não recorri. Contudo, ó minha benigníssima Mãe, não me recuseis o Vosso socorro; pois sei que com ele serei vencedor., Sim, sei que vireis em meu socorro, se a Vós me recomendar; mas temo as ocasiões de pecar,, receio deixar então de invocar o Vosso Auxílio,, e deste modo perder-me., É esta a graça que peço, e Vos conjuro que me concedais;, fazei, ó Maria, que eu aVós recorra, em todos os assaltos que possam me conduzir ao inferno, e que eu possa dizer-Vos continuamente:, Maria, ajudai-me! Mãe do Perpétuo Socorro. Não permitais que eu perca o meu Deus!

Pai Nosso 1x

Ave Maria 3x

Ó Mãe do Perpétuo Socorro, ao terminar esta novena, confio-me inteiramente a vós. Alcancei para mim e para os meus pedidos a misericórdia e a graça que tanto precisamos, se for para a glória de Deus. Amém.

PEQUENA LADAINHA À N. SRA. DO PERPÉTUO SOCORRO:

Saúde dos enfermos. Todos: Rogai por nós.

Auxílio dos Necessitados: Todos: Rogai por nós.

Consoladora dos aflitos Todos: Rogai por nós.

Refúgio dos pecadores Todos: Rogai por nós.

Padroeira da Família Excelsior: Rogai por nós.

Rainha dos apóstolos Todos: Enviai-nos muitas e santas vocações.

Rogai por nós, ó Mãe do Perpétuo Socorro.

Todos: Para que sejamos dignos das promessas de Cristo…

ORAÇÃO

Ó Deus fiel e misericordioso,, que nos destes a graça de venerar a

vossa bem aventurada Mãe, sob o título de Nossa Senhora do

Perpétuo Socorro, concedei-nos que em todas as nossas

necessidades, sejamos acompanhados pela proteção da Virgem Maria,

e que, depois de nossa peregrinação nesta vida, alcancemos o prêmio

da Redenção Eterna. Vós que viveis e reinais, por todos os séculos dos

séculos. Amém!

CONSAGRAÇÃO À NOSSA SENHORA DO PERPÉTUO

SOCORRO

Santíssima Virgem Maria, Mãe de Deus, a quem tanto me apraz honrar

sob o belo titulo de Mãe do Perpétuo Socorro, eu (dizer seu nome e

dos participantes da sua família) ainda que indigno/a de ser o vosso

servo, animado contudo pela vossa admirável bondade e entusiasmado

pelo desejo de vos servir, vos escolho hoje em presença do meu anjo

da guarda e de toda a côrte celeste, para minha Mãe, e tomo a firme

resolução de vos amar e servir sempre daqui em diante, e fazer tudo o

que me for possível para que sejais amada e servida também pelos

outros.

Ó Mãe de Deus, minha boa e muito amável Mãe, pelo sangue do vosso

Divino Filho, derramado por nosso amor, suplico-vos me recebais para

sempre em o número dos vossas filhos e servos dedicados. Assisti-me

em todos os meus pensamentos, palavras e ações, até ao fim da vida,

de sorte que todos os meus passos e suspiros tenham por único fim

dar maior glória a Deus; fazei, pela vossa poderosa intercessão, que eu

não ofenda jamais o meu amadíssimo Jesus, mas O glorifique e ame.

Fazei que vos ame também, ó minha Mãe queridíssima, a fim de que

eu tenha um dia a felicidade de vos ter e amar no santo paraíso, por

séculos dos séculos. Assim seja. Ó Maria, minha Mãe, recomendo-vos

a minha alma, principalmente na hora da minha morte. Nossa Senhora

do Perpétuo Socorro, rogai por nós!

ORAÇÃO PELA FAMÍLIA EXCELSIOR

Ó Mãe do Perpétuo Socorro, nós vos suplicamos, com toda a força

do nosso coração, para que ampare cada membro da Família

Excelsior. Que o Vosso olhar esteja sempre atento para cada ouvinte

da Rede Excelsior de Comunicação. Pedimos de modo particular por

aqueles que nos escutam enquanto se deslocam para o trabalho, nas

suas atividades domésticas, nas atividades educativas, nos momentos

de lazer, nos eventos culturais e esportivos. Permita-lhes receberem o

Vosso cuidado materno, tal como o Menino Jesus em seus braços.

Continua nos dando condições para levar a Voz do Senhor do

Bonfim, vosso Filho amado, sobretudo, para todos aqueles que se

encontram nos abrigos de idosos, leitos dos hospitais, nas madrugadas

solitárias, nos contextos prisionais, e em toda e qualquer dificuldade.

Sede para eles refúgio e esperança. Dai-lhes paz e proteção.

Sabemos, ó Mãe do Perpétuo Socorro, o quão difícil é a

manutenção desta obra da ação evangelizadora, por isto pedimos a

sua poderosa intercessão junto a Deus, para que envie novos sócios-

missionários para a Família Excelsior. Ajudai-nos nos caminhos da vida

e sobretudo, Mãe, conduza-nos para o verdadeiro caminho que é teu

Filho Jesus. Amém!

BÊNÇÃO COM O ÍCONE DE NOSSA SENHORA DO

PERPÉTUO SOCORRO

Ó Maria, Mãe do Perpétuo Socorro, abençoai o povo deste bairro,

desta cidade e todos os vossos devotos. Protegei os pais, as mães, os

jovens, os adolescentes, as crianças e os idosos. Restituí a saúde aos

enfermos. Confortai os aflitos. Ajudai-nos a resolver os nossos

problemas pessoais e familiares. Sede nossa Mãe do Perpétuo Socorro

e dai-nos a vossa bênção.

Em nome do Pai, do Filho e do Espírito Santo.

Amém.

